import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1786889090000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>Three variables, all read once at startup. There is no config file.</p><h2 id="hetzner-api-token" tabindex="-1"><code>HETZNER_API_TOKEN</code> <a class="header-anchor" href="#hetzner-api-token" aria-label="Permalink to “HETZNER_API_TOKEN”">​</a></h2><p><strong>Required.</strong> Hetzner Cloud API token for the project that holds the zones.</p><p>Create it in the <a href="https://console.hetzner.com" target="_blank" rel="noreferrer">Cloud Console</a> under <strong>your project → Security → API tokens</strong>. Choose <strong>Read &amp; Write</strong> for the full tool set, <strong>Read</strong> for the query tools only.</p><ul><li>Sent as <code>Authorization: Bearer …</code> on every request.</li><li>Deleted from <code>process.env</code> once read.</li><li>Never logged, never included in an error message or a tool result.</li></ul><p>Without it the server still starts, completes the MCP handshake and lists all tools — registries and sandbox inspectors need that — but every call fails with setup instructions and nothing reaches the API.</p><div class="danger custom-block"><p class="custom-block-title custom-block-title-default">DANGER</p><p>A token from the old DNS Console (<code>dns.hetzner.com</code>) does not work. That API was shut down in May 2026.</p></div><h2 id="hetzner-read-only" tabindex="-1"><code>HETZNER_READ_ONLY</code> <a class="header-anchor" href="#hetzner-read-only" aria-label="Permalink to “HETZNER_READ_ONLY”">​</a></h2><p><strong>Optional</strong>, default <code>false</code>. Accepts <code>true</code>, <code>1</code> or <code>yes</code>, case-insensitively.</p><p>When set, only these seven tools are registered:</p><p><code>list_zones</code> · <code>get_zone</code> · <code>export_zonefile</code> · <code>list_rrsets</code> · <code>get_rrset</code> · <code>list_zone_actions</code> · <code>get_zone_action</code></p><p>The write tools are not registered at all, so a client asking for <code>delete_zone</code> gets a protocol-level &quot;tool not found&quot;. This is not a call-time refusal — there is no code path from a write request to the API.</p><h2 id="hetzner-api-base-url" tabindex="-1"><code>HETZNER_API_BASE_URL</code> <a class="header-anchor" href="#hetzner-api-base-url" aria-label="Permalink to “HETZNER_API_BASE_URL”">​</a></h2><p><strong>Optional</strong>, default <code>https://api.hetzner.cloud/v1</code>. Trailing slashes are stripped.</p><p>Intended for pointing at a local mock during development. Validated before anything is sent, because the token goes to whatever this names:</p><table tabindex="0"><thead><tr><th>Rule</th><th>On violation</th></tr></thead><tbody><tr><td>Must parse as a URL</td><td>exit</td></tr><tr><td>Must be <code>https</code> (<code>http</code> only for loopback hosts)</td><td>exit</td></tr><tr><td>Must not contain credentials (<code>https://user:pass@…</code>)</td><td>exit</td></tr><tr><td>Non-default host</td><td>warning</td></tr></tbody></table><p>Loopback hosts are <code>localhost</code>, <code>127.0.0.1</code> and <code>[::1]</code>.</p><p>The value is never printed back on a parse failure — a malformed URL can still contain a <code>user:token@</code> part, and startup messages end up in client logs.</p><p>Also deleted from <code>process.env</code> once read.</p><h2 id="not-configurable" tabindex="-1">Not configurable <a class="header-anchor" href="#not-configurable" aria-label="Permalink to “Not configurable”">​</a></h2><p>For completeness, the constants you might otherwise look for:</p><table tabindex="0"><thead><tr><th>Behaviour</th><th>Value</th></tr></thead><tbody><tr><td>Request timeout</td><td>30 s</td></tr><tr><td>Redirect handling</td><td>refused</td></tr><tr><td>Confirmation token TTL</td><td>5 minutes, single use</td></tr><tr><td>Pending confirmation tokens</td><td>100 max, oldest evicted</td></tr><tr><td>Per-value truncation</td><td>4 000 characters</td></tr><tr><td>Per-result truncation</td><td>200 000 characters</td></tr><tr><td>Error body truncation</td><td>2 000 characters; HTML dropped</td></tr><tr><td>Redacted key pattern</td><td><code>tsig_key</code>, <code>token</code>, <code>secret</code>, <code>password</code>, <code>credential</code></td></tr></tbody></table>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};